      "css": "/* style.css */\nbody\n{\n    margin: 0;\n    padding: 0;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 100vh;\n    background-image: url(pexels-brand-&-palms-768943.jpg);\n    background-position: center;\n    background-size: cover;\n    font-family: sans-serif;\n}\n.calender\n{\n    width: 600px;\n    height: auto;\n    background: #fff;\n    box-sizing: border-box;\n    box-shadow: 0 5px 50px rgba(0,0,0,0.5)\n}\n.calender .image\n{\n    width: 100%;\n    height: 200px;\n    background: url(ethan-robertson-SYx3UCHZJlo-unsplash.jpg);\n    background-position: center;\n    background-size: cover;\n    padding: 20px;\n    box-sizing: border-box;\n}\n.calender .image h2,\n.calender .image h3\n{\n    margin: 0;\n    padding: 0;\n    color: #fff;\n    text-shadow: 0 2px 2px rgba(0,0,0,.8);\n}\n.calender .image h3\n{\n    font-weight: 500;\n}\n.calender .date\n{\n    padding: 20px;\n    display: grid;\n    grid-template-columns: repeat(auto-fit, minmax(70px, 1fr));\n    grid-gap: 10px;\n    box-sizing: border-box;\n}\n.calender .date div\n{\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 25px;\n    color: #252526;\n}\n.calender .date div.day\n{\n    font-weight: 700;\n}\n.calender .date div.day:first-child,\n.calender .date div.number:nth-child(7n + 1)\n{\n    color: #ff685d;\n    font-weight: 700;\n}\n.calender .date div.number.active,\n.calender .date div.number:hover\n{\n    background: #009688;\n    color: #fff;\n    font-weight: 700;\n    cursor: pointer;\n}"
