      "css": "/* style.css */\n@import url('https://fonts.googleapis.com/css2?family=Lato:wght@100&display=swap');\nbody \n{\n    margin: 0;\n    padding: 0;\n    background-size: cover;\n    font-family: 'Lato', sans-serif;\n    background-color: #000;\n}\ndiv\n{\n    position: absolute;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%,-50%) skewY(-5deg);\n    border: 4px solid #fff;\n    padding: 20px 50px;\n    border-radius: 10px;\n    box-shadow: 0 0 10px #1eff4e, 0 0 30px #1eff4e, inset 0 0 10px #1eff4e, inset 0 0 30px #1eff4e;\n    animation: animate .1s linear infinite;\n}\ndiv::before\n{\n    content: '';\n    position: absolute;\n    bottom: 80px;\n    left: 0;\n    width: 100%;\n    height: 4px;\n    background: #fff;\n    box-shadow:  0 0 10px #1eff4e, 0 0 30px #1eff4e;\n    z-index: 1;\n}\ndiv::after\n{\n    content: '';\n    position: absolute;\n    top: 80px;\n    left: 0;\n    width: 100%;\n    height: 4px;\n    background: #fff;\n    box-shadow:  0 0 10px #1eff4e, 0 0 30px #1eff4e;\n    z-index: 1;\n}\n{\n    content: '';\n    position: absolute;\n    bottom: 80px;\n    left: 0;\n    width: 100%;\n    height: 4px;\n    background: #fff;\n    box-shadow:  0 0 10px #1eff4e, 0 0 30px #1eff4e;\n    z-index: 1;\n}\nh1 \n{\n    margin: 0;\n    padding: 0;\n    font-size: 9em;\n    color: #fff;\n    text-shadow: 0 0 10px #1eff4e, 0 0 20px #1eff4e, 0 0 120px #1eff4e;\n}\nh1 span\n{\n    animation: animate .5s linear infinte;\n}\nh1 span:nth-child(1)\n{\n    animation-delay: .25s\n}\nh1 span:nth-child(2)\n{\n    animation-delay: .2s\n}\nh1 span:nth-child(3)\n{\n    animation-delay: .35s\n}\nh1 span:nth-child(4)\n{\n    animation-delay: .4s\n}\nh1 span:nth-child(5)\n{\n    animation-delay: .45s\n}\nh1 span:nth-child(6)\n{\n    animation-delay: .5s\n}\n@keyframes animate\n{\n    0%\n    {\n        opacity: 1;\n    }\n    30%\n    {\n        opacity: 1;\n    }\n    40%\n    {\n        opacity: .5;\n    }\n    50%\n    {\n        opacity: 1;\n    }\n    100%\n    {\n        opacity: 1;\n    }\n}"
