      "css": "/* style.css */\nbody \n{\n    margin: 0;\n    padding: 0;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    min-height: 100vh;\n    background: #003e46;\n    font-family: arial;\n}\n.container\n{\n    width: 1000px;\n    display: flex;\n    flex-wrap: wrap;\n    justify-content: space-between;\n}\n.box\n{\n    position: relative;\n    width: 300px;\n    height: 400px;\n    background: #000;\n    box-shadow: 0 30px 30px rgba(0,0,0,0.5);\n}\n.box .imgBx\n{\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n}\n.box .imgBx img\n{\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    object-fit: cover;\n    transition: 0.5s;\n}\n.box:hover .imgBx img\n{\n    opacity: 0;\n}\n.box .content\n{\n    position: absolute;\n    bottom: 20px;\n    left: 10%;\n    width: 80%;\n    height: 60px;\n    background: #fff;\n    transition: 0.5s;\n    overflow: hidden;\n    \n    padding: 15px;\n    box-sizing: border-box;\n}\n.box:hover .content\n{\n    width: 100%;\n    height: 100%;\n    bottom: 0;\n    left: 0;\n}\n.box .content h3\n{\n    margin: 0;\n    padding: 0;\n    font-size: 20px;\n}\n.box .content p\n{\n    margin: 10px 0 0;\n    padding: 0;\n    opacity: 0;\n    line-height: 1.2rem;\n    transition: 0.5s;\n    text-align: justify;\n}\n.box:hover .content p\n{\n    opacity: 1;\n    transition-delay: 0.5s;\n}"
