      "html": "<div class=\"form\">\n         <h2>Login</h2>\n         <div class=\"input\">\n             <div class=\"inputbox\">\n                 <label for=\"name\">Username</label>\n                 <input type=\"text\" name=\"name\" placeholder=\"example@xyz.com\">\n             </div>\n             <div class=\"inputbox\">\n                 <label for=\"pass\">Password</label>\n                 <input type=\"password\" name=\"pass\" placeholder=\"**********\">\n             </div>\n             <div class=\"inputbox\">\n                 <input type=\"submit\" value=\"Sign In\">\n             </div>\n             <div class=\"forget\">\n                <a href=\"#\">Forget Password?</a>\n             </div>\n             <div class=\"signup\">\n                 <a href=\"#\">Sign Up</a>\n             </div>   \n         </div>\n     </div>",
      "css": "/* style.css */\n*\n{\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\nbody\n{\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    min-height: 100vh;\n    background: #ebf5fc;\n}\n.form\n{\n    position: relative;\n    width: 350px;\n    padding: 40px 40px 60px;\n    background: #ebf5fc;\n    border-radius: 10px;\n    text-align: center;\n    box-shadow: -5px -5px 15px rgba(255,255,255,0.8),\n                5px 5px 10px rgba(0,0,0,0.1);\n}\n.form h2\n{\n    color: #32a3b1;\n    font-weight: 500;\n    font-family: arial;\n}\n.form .input\n{\n    text-align: left;\n    margin-top: 40px;\n}\n.form .input .inputbox\n{\n    margin-top: 20px;\n}\n.form .input .inputbox label\n{\n    display: block;\n    color: #868686;\n    margin-bottom: 5px;\n    font-size: 18px;\n}\n.form .input .inputbox input\n{\n    width: 100%;\n    height: 50px;\n    background: #ebf5fc;\n    border: none;\n    outline: none;\n    border-radius: 40px;\n    padding: 5px 15px;   \n    font-size: 18px;\n    color: #32a3b1;\n    box-shadow: inset -2px -2px 6px rgba(255,255,255,1),\n                inset 2px 2px 6px rgba(0,0,0,0.1);\n}\n.form .input .inputbox input[type=\"submit\"]\n{\n    margin-top: 20px;\n    box-shadow: -2px -2px 6px rgba(255,255,255,1),\n                 2px 2px 6px rgba(0,0,0,0.1);\n}\n.form .input .inputbox input[type=\"submit\"]:hover\n{\n    color: #006c9c;\n    margin-top: 20px;\n    box-shadow: inset -2px -2px 6px rgba(255,255,255,1),\n                 inset 2px 2px 6px rgba(0,0,0,0.1);\n}\n.form .input .inputbox input::placeholder\n{\n    color: #bdcada;\n    font-family: cursive;\n    font-size: 18px;\n}\n.forget\n{\n    margin-top: 30px;\n    text-align: center;\n}\n.forget a\n{\n    text-decoration: none;\n    font-size: 18px;\n    color: #999aaa;\n}\n.forget a:hover\n{\n    color: #444;\n}\n.signup\n{\n    margin-top: 30px;\n    text-align: center;\n}\n.signup a\n{\n    text-decoration: none;\n    color: #ff0047;\n    font-size: 18px;\n    font-family: arial;\n}\n.signup a:hover\n{\n    color: #4700ff;\n}"
