      "css": "/* style.css */\nbody\n{\n    margin: 0;\n    padding: 0;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    min-height: 100vh;\n    background: #060c21;\n    font-family: arial;\n}\n.box\n{\n    position: relative;\n    width: 300px;\n    height: 400px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    background: #060c21;\n}\n.box:before\n{\n    content: '';\n    position: absolute;\n    top: -2px;\n    left: -2px;\n    right: -2px;\n    bottom: -2px;\n    background: #fff;\n    z-index: -1;\n}\n.box:after\n{\n    content: '';\n    position: absolute;\n    top: -2px;\n    left: -2px;\n    right: -2px;\n    bottom: -2px;\n    background: #fff;\n    z-index: -2;\n    filter: blur(40px);\n}\n.box:before,\n.box:after\n{\n    background: linear-gradient(235deg,#89ff00,#060c21,#00bcd4);\n}\n.content\n{\n    padding: 10px;\n    box-sizing: border-box;\n    color: #fff;\n}"
