      "css": "/* style.css */\n@import url('https://fonts.googleapis.com/css2?family=Bad+Script&display=swap');\nbody\n{\n    margin: 0;\n    padding: 0;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    min-height: 100vh;\n    background-color: #000;\n    font-family: 'Bad Script', cursive;\n    overflow: hidden;\n}\nh1\n{\n    margin: 0;\n    padding: 0;\n    color: transparent;\n    font-size: 10em;\n}\nh1 span\n{\n    display: table-cell;\n    animation: animate 1s linear infinite;\n}\nh1 span:nth-child(7n+1)\n{\n    animation-delay: 0.5s;\n}\nh1 span:nth-child(7n+2)\n{\n    animation-delay: 1.25s;\n}\nh1 span:nth-child(7n+3)\n{\n    animation-delay: 2.35s;\n}\nh1 span:nth-child(7n+4)\n{\n    animation-delay: 2.75s;\n}\nh1 span:nth-child(7n+5)\n{\n    animation-delay: 1s;\n}\nh1 span:nth-child(7n+6)\n{\n    animation-delay: 1.35s;\n}\nh1 span:nth-child(7n+7)\n{\n    animation-delay: 1.25s;\n}\n@keyframes animate\n{\n    0%,100%\n    {\n        color: #fff;\n        filter: blur(2px);\n        text-shadow: 0 0 10px #00b3ff,\n                     0 0 20px #00b3ff,\n                     0 0 40px #00b3ff,\n                     0 0 800px #00b3ff,\n                     0 0 120px #00b3ff,\n                     0 0 200px #00b3ff,\n                     0 0 300px #00b3ff,\n                     0 0 400px #00b3ff;\n    }\n}"
