      "css": "/* style.css */\n*\n{\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\nbody\n{\n    display: flex;\n    background: #eafdff;\n}\n.container\n{\n    width: 100%;\n    min-height: 100vh;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    flex-wrap: wrap;\n}\n.container .loader\n{\n    position: relative;\n    height: 150px;\n    width: 150px;\n    margin: 100px;\n}\n.container .loader.one span\n{\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    display: block;\n    background: #5989ff;\n    border-radius: 50%;\n    animation: animate ease-in-out 2s infinite;\n}\n.container .loader.one span:nth-child(2)\n{\n    background: rgba(56,100,241,0.05);\n    backdrop-filter: blur(10px);\n    border: 1px solid rgba(255,255,255,0.1);\n    animation-delay: -1s;\n}\n@keyframes animate\n{\n    0%,100%\n    {\n        transform: translateX(-80px);\n    }\n    50%\n    {\n        transform: translateX(80px);\n    }\n}\n.container .loader.one span:before,\n.container .loader.two span:nth-child(1):before\n{\n    content: '';\n    position: absolute;\n    bottom: -100px;\n    left: -20px;\n    width: 140px;\n    height: 40px;\n    border-radius: 50%;\n    background: radial-gradient(rgba(0,0,0,0.04),transparent,transparent);\n}\n.container .loader.two\n{\n    position: relative;\n    width: 180px;\n    height: 180px;\n}\n.container .loader.two span:nth-child(1)\n{\n    position: absolute;\n    top: 10px;\n    left: 10px;\n    right: 10px;\n    bottom: 10px;\n    background: rgba(233,30,99,0.05);\n    border-radius: 50%;\n    backdrop-filter: blur(10px);\n    border: 1px solid rgba(255,255,255,0.1);\n    z-index: 2;\n}\n.container .loader.two span:nth-child(2)\n{\n    position: absolute;\n    top: 0;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    display: block;\n    border-radius: 50%;\n    z-index: 1;\n    overflow: hidden;\n    animation: rotateCircle 2s linear infinite;\n}\n@keyframes rotateCircle\n{\n    0%\n    {\n        transform: rotate(0deg);\n    }\n    100%\n    {\n        transform: rotate(360deg);\n    }\n}\n.container .loader.two span:nth-child(2)::before\n{\n    content: '';\n    position: absolute;\n    top: -50%;\n    left: -50%;\n    width: 100%;\n    height: 100%;\n    background: #ff6198;\n    \n}"
