      "html": "<div class=\"container\">\r\n        <div class=\"loader one\">\r\n            <span></span>\r\n            <span></span>\r\n        </div>\r\n        <div class=\"loader two\">\r\n            <span></span>\r\n            <span></span>\r\n        </div>\r\n    </div>",
      "css": "/* style.css */\n*\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n}\r\nbody\r\n{\r\n    display: flex;\r\n    background: #eafdff;\r\n}\r\n.container\r\n{\r\n    width: 100%;\r\n    min-height: 100vh;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    flex-wrap: wrap;\r\n}\r\n.container .loader\r\n{\r\n    position: relative;\r\n    height: 150px;\r\n    width: 150px;\r\n    margin: 100px;\r\n}\r\n.container .loader.one span\r\n{\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    display: block;\r\n    background: #5989ff;\r\n    border-radius: 50%;\r\n    animation: animate ease-in-out 2s infinite;\r\n}\r\n.container .loader.one span:nth-child(2)\r\n{\r\n    background: rgba(56,100,241,0.05);\r\n    backdrop-filter: blur(10px);\r\n    border: 1px solid rgba(255,255,255,0.1);\r\n    animation-delay: -1s;\r\n}\r\n@keyframes animate\r\n{\r\n    0%,100%\r\n    {\r\n        transform: translateX(-80px);\r\n    }\r\n    50%\r\n    {\r\n        transform: translateX(80px);\r\n    }\r\n}\r\n.container .loader.one span:before,\r\n.container .loader.two span:nth-child(1):before\r\n{\r\n    content: '';\r\n    position: absolute;\r\n    bottom: -100px;\r\n    left: -20px;\r\n    width: 140px;\r\n    height: 40px;\r\n    border-radius: 50%;\r\n    background: radial-gradient(rgba(0,0,0,0.04),transparent,transparent);\r\n}\r\n.container .loader.two\r\n{\r\n    position: relative;\r\n    width: 180px;\r\n    height: 180px;\r\n}\r\n.container .loader.two span:nth-child(1)\r\n{\r\n    position: absolute;\r\n    top: 10px;\r\n    left: 10px;\r\n    right: 10px;\r\n    bottom: 10px;\r\n    background: rgba(233,30,99,0.05);\r\n    border-radius: 50%;\r\n    backdrop-filter: blur(10px);\r\n    border: 1px solid rgba(255,255,255,0.1);\r\n    z-index: 2;\r\n}\r\n.container .loader.two span:nth-child(2)\r\n{\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    display: block;\r\n    border-radius: 50%;\r\n    z-index: 1;\r\n    overflow: hidden;\r\n    animation: rotateCircle 2s linear infinite;\r\n}\r\n@keyframes rotateCircle\r\n{\r\n    0%\r\n    {\r\n        transform: rotate(0deg);\r\n    }\r\n    100%\r\n    {\r\n        transform: rotate(360deg);\r\n    }\r\n}\r\n.container .loader.two span:nth-child(2)::before\r\n{\r\n    content: '';\r\n    position: absolute;\r\n    top: -50%;\r\n    left: -50%;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: #ff6198;\r\n    \r\n}"
