      "html": "<ul>\r\n         <li>\r\n             <a href=\"#\">\r\n                 <span>Home</span>\r\n                 <span>Home</span>\r\n             </a>\r\n         </li>\r\n     </ul>\r\n     <ul>\r\n         <li>\r\n             <a href=\"#\">\r\n                 <span>About</span>\r\n                 <span>About</span>\r\n             </a>\r\n         </li>\r\n     </ul>\r\n     <ul>\r\n         <li>\r\n             <a href=\"#\">\r\n                 <span>Service</span>\r\n                 <span>Service</span>\r\n             </a>\r\n         </li>\r\n     </ul>\r\n     <ul>\r\n         <li>\r\n             <a href=\"#\">\r\n                 <span>Portfolio</span>\r\n                 <span>Portfolio</span>\r\n             </a>\r\n         </li>\r\n     </ul>\r\n     <ul>\r\n         <li>\r\n             <a href=\"#\">\r\n                 <span>Contact</span>\r\n                 <span>Contact</span>\r\n             </a>\r\n         </li>\r\n     </ul>",
      "css": "/* style.css */\n@import url('https://fonts.googleapis.com/css2?family=Roboto:wght@400;500;700;900&display=swap');\r\nbody\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    min-height: 100vh;\r\n    background: #000;\r\n    font-family: 'Roboto', sans-serif;\r\n}\r\nul\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    display: flex;\r\n}\r\nul li\r\n{\r\n    position: relative;\r\n    list-style: none;\r\n    margin: 0 10px;\r\n}\r\nul li a\r\n{\r\n    position: relative;\r\n    height: 20px;\r\n    display: block;\r\n    text-decoration: none;\r\n    overflow: hidden;\r\n    text-transform: uppercase;\r\n    font-weight: 700;\r\n}\r\nul li a span\r\n{\r\n    width: 100%;\r\n    height: 100%;\r\n    display: block;\r\n    transition: 0.5s;\r\n    color: #fff;\r\n}\r\nul li a span:nth-child(1)\r\n{\r\n    color: #444;\r\n}\r\nul li a span:nth-child(2)\r\n{\r\n    color: #fff;\r\n}\r\nul li:hover a span:nth-child(1)\r\n{\r\n    transform: translateY(-100%);\r\n}\r\nul li:hover a span:nth-child(2)\r\n{\r\n    transform: translateY(-100%);\r\n}\r\nul li:before\r\n{\r\n    content: '';\r\n    position: absolute;\r\n    top: -90px;\r\n    left: -65px;\r\n    width: 200px;\r\n    height: 200px;\r\n    background: #00f;\r\n    z-index: -1;\r\n    opacity: 0;\r\n    transition: 0.5s;\r\n    transform: translateY(100px);\r\n}\r\nul li:hover:before\r\n{\r\n    opacity: 1;\r\n    transition-delay: 0.5s;\r\n    transform: translateY(0px);\r\n}\r\nul li:nth-child(1):before\r\n{\r\n    background: url(i1.jpg);\r\n    background-size: cover;\r\n}\r\nul li:nth-child(2):before\r\n{\r\n    background: url(mountain.jpg);\r\n    background-size: cover;\r\n}\r\nul li:nth-child(3):before\r\n{\r\n    background: url(Space.jpg);\r\n    background-size: cover;\r\n}\r\nul li:nth-child(4):before\r\n{\r\n    background: url(Water.jpg);\r\n    background-size: cover;\r\n}\r\nul li:nth-child(5):before\r\n{\r\n    background: url(Hill.jpg);\r\n    background-size: cover;\r\n}"
