      "css": "/* style.css */\nbody\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    height: 100vh;\r\n    background-image: url(pexels-brand-&-palms-768943.jpg);\r\n    background-position: center;\r\n    background-size: cover;\r\n    font-family: sans-serif;\r\n}\r\n.calender\r\n{\r\n    width: 600px;\r\n    height: auto;\r\n    background: #fff;\r\n    box-sizing: border-box;\r\n    box-shadow: 0 5px 50px rgba(0,0,0,0.5)\r\n}\r\n.calender .image\r\n{\r\n    width: 100%;\r\n    height: 200px;\r\n    background: url(ethan-robertson-SYx3UCHZJlo-unsplash.jpg);\r\n    background-position: center;\r\n    background-size: cover;\r\n    padding: 20px;\r\n    box-sizing: border-box;\r\n}\r\n.calender .image h2,\r\n.calender .image h3\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    color: #fff;\r\n    text-shadow: 0 2px 2px rgba(0,0,0,.8);\r\n}\r\n.calender .image h3\r\n{\r\n    font-weight: 500;\r\n}\r\n.calender .date\r\n{\r\n    padding: 20px;\r\n    display: grid;\r\n    grid-template-columns: repeat(auto-fit, minmax(70px, 1fr));\r\n    grid-gap: 10px;\r\n    box-sizing: border-box;\r\n}\r\n.calender .date div\r\n{\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    height: 25px;\r\n    color: #252526;\r\n}\r\n.calender .date div.day\r\n{\r\n    font-weight: 700;\r\n}\r\n.calender .date div.day:first-child,\r\n.calender .date div.number:nth-child(7n + 1)\r\n{\r\n    color: #ff685d;\r\n    font-weight: 700;\r\n}\r\n.calender .date div.number.active,\r\n.calender .date div.number:hover\r\n{\r\n    background: #009688;\r\n    color: #fff;\r\n    font-weight: 700;\r\n    cursor: pointer;\r\n}"
