    "code": {
      "html": "<div class=\"loader\">\r\n         <div style=\"--i:0\"></div>\r\n         <div style=\"--i:1\"></div>\r\n         <div style=\"--i:2\"></div>\r\n         <div style=\"--i:3\"></div>\r\n         <div style=\"--i:4\"></div>\r\n     </div>",
      "css": "/* style.css */\n*\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n}\r\nbody\r\n{\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    background: #edf1f4;\r\n    min-height: 100vh;\r\n}\r\n.loader\r\n{\r\n    display: flex;\r\n    flex-direction: row;\r\n}\r\n.loader div\r\n{\r\n    position: relative;\r\n    width: 40px;\r\n    height: 200px;\r\n    margin: 20px;\r\n    overflow: hidden;\r\n    border-radius: 40px;\r\n    background: linear-gradient(to bottom, rgba(0, 0, 0, 0.05, #edf1f4));\r\n    border: 2px solid #edf1f4;\r\n    box-shadow: 15px 15px 20px rgba(0, 0, 0, 0.1),\r\n                -15px -15px 20px #fff,\r\n                inset -5px -5px 5px rgba(255, 255, 255, 0.5),\r\n                inset 5px 5px 5px rgba(0, 0, 0, 0.05);\r\n}\r\n.loader div::before\r\n{\r\n    content: '';\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    z-index: 10;\r\n    border-radius: 40px;\r\n    box-shadow: 15px 15px 20px rgba(0, 0, 0, 0.1),\r\n                -15px -15px 20px #fff,\r\n                inset -5px -5px 5px rgba(255, 255, 255, 0.5),\r\n                inset 5px 5px 5px rgba(0, 0, 0, 0.05);\r\n}\r\n.loader div::after\r\n{\r\n    content: '';\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 36px;\r\n    height: 36px;\r\n    background: #fff;\r\n    border-radius: 50%;\r\n    box-shadow: inset -5px -5px 5px rgba(0, 0, 0, 0.2),\r\n                 0 420px 0 400px #2196f3;\r\n    animation: animate 2.5s ease-in-out infinite;\r\n    transform: translateY(160px);\r\n    animation-delay: calc(0.5s * var(--i));\r\n}\r\n@keyframes animate\r\n{\r\n    0%\r\n    {\r\n        transform: translateY(160px);\r\n        filter: hue-rotate(180deg);\r\n    }\r\n    50%\r\n    {\r\n        transform: translateY(0);\r\n    }\r\n    100%\r\n    {\r\n        transform: translateY(160px);\r\n        filter: hue-rotate(0deg);\r\n    }\r\n}"
    }
