    "code": {
      "html": "<div class=\"popup\">\n        <div class=\"contentBox\">\n            <div class=\"imgBx\">\n                <img src=\"gift.png\" alt=\"\">\n            </div>\n            <div class=\"content\">\n                <div>\n                   <div class=\"close\"></div>\n                    <h3>Spacial Offer</h3>\n                    <h2>80<sup>%</sup><span> Off</span></h2>\n                    <p>lorem ipsum dollar sumit</p>\n                    <a href=\"#\">Get The Deal</a>\n                </div>\n            </div>\n        </div>\n    </div>\n\n<script>\n    const popup = document.querySelector('.popup');\n    const close = document.querySelector('.close');\n    \n    window.onload = function(){\n        setTimeout(function(){\n            popup.style.display = \"block\"\n        }, 2000)\n    }\n    \n    close.addEventListener('click', () => {\n        popup.style.display = \"none\";\n    })\n</script>",
      "css": "/* style.css */\n*\n{\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n    font-family: arial;\n}\nbody\n{\n    min-height: 100vh;\n    background: #6cb1ff;\n}\n.popup\n{\n    position: fixed;\n    top: 50%;\n    left: 50%;\n    transform: translate(-50%,-50%);\n    display: none;\n}\n.contentBox\n{\n    position: relative;\n    width: 600px;\n    height: 400px;\n    background: #fff;\n    border-radius: 20px;\n    display: flex;\n    box-shadow: 0 5px 15px rgba(0,0,0,0.1);\n}\n.contentBox .imgBx\n{\n    position: relative;\n    width: 300px;\n    height: 400px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n}\n.contentBox .imgBx::before\n{\n    content: '';\n    position: absolute;\n    width: 250px;\n    height: 250px;\n    background: #e7ffe0;\n    border-radius: 50%;\n}\n.contentBox .imgBx img\n{\n    position: relative;\n    max-width: 250px; \n}\n.contentBox .content\n{\n    position: relative;\n    width: 300px;\n    height: 400px;\n    display: flex;\n    justify-content: center;\n    align-items: center;\n}\n.contentBox .content h3\n{\n    color: #333;\n    line-height: 1em;\n    font-weight: 300;\n    font-size: 2em;\n}\n.contentBox .content h2\n{\n    font-size: 4em;\n    color: #ff4d54;\n    line-height: 1em;\n}\n.contentBox .content h2 span\n{\n    color: #333;\n    font-size: 0.75em;\n    text-transform: uppercase;\n}\n.contentBox .content p\n{\n    font-weight: 300;\n}\n.contentBox .content a\n{\n    display: inline-block;\n    padding: 10px 20px;\n    background: #ff4d54;\n    color: #fff;\n    margin-top: none;\n    border-radius: 10px;\n    text-decoration: none;\n}\n.close\n{\n    position: absolute;\n    top: 20px;\n    right: 20px;\n    width: 40px;\n    height: 40px;\n    background: #f3f3f3 url(close.png);\n    background-repeat: no-repeat;\n    background-size: 10px;\n    background-position: center;\n    cursor: pointer;\n    border-radius: 50%;\n    z-index: 10;\n}"
    }
