      "html": "<section>\n        <div class=\"clouds\">\n            <img src=\"cloud1.png\" alt=\"\" style=\"--i:1;\">\n            <img src=\"cloud2.png\" alt=\"\" style=\"--i:2;\">\n            <img src=\"cloud3.png\" alt=\"\" style=\"--i:3;\">\n        </div>\n        <div class=\"runway\"></div>\n        <img src=\"air.png\" alt=\"plane\" class=\"plane\">\n    </section>",
      "css": "/* style.css */\n*\n{\n    margin: 0;\n    padding: 0;\n    box-sizing: border-box;\n}\n\nbody\n{\n    overflow: hidden;\n}\nsection\n{\n    display: flex;\n    justify-content: center;\n    align-items: center;\n    height: 100vh;\n    background: #034071;\n}\nsection .runway\n{\n    position: relative;\n    width: 400px;\n    height: 100vh;\n    background: #1378bc;\n    border-left: 20px solid rgba(0,0,0,0.25);\n    border-right: 20px solid rgba(0,0,0,0.25);\n    transition: transform 3s;\n    transition-delay: 1s;\n    transform-origin: top;\n}\nsection:active .runway\n{\n    transform: scaleX(0.7) scaleY(0);\n    transform-origin: bottom;\n}\nsection .runway::before\n{\n    content: '';\n    position: absolute;\n    top: 0;\n    left: 50%;\n    transform: translateX(-50%);\n    width: 15px;\n    height: 100%;\n    background: repeating-linear-gradient(transparent 0%, transparent 50%, #fff 50%, #fff 100%);\n    background-size: 20px 320px;\n    animation: animateRunway 0.5s linear infinite;\n}\nsection:active .runway::before\n{\n    animation: animateRunway 0.25s linear infinite;\n}\n@keyframes animateRunway\n{\n    0%\n    {\n        background-position-y: 0;\n    }\n    100%\n    {\n        background-position-y: 640px;\n    }\n}\n.plane\n{\n    position: absolute;\n    bottom: 100px;\n    max-width: 250px;\n    pointer-events: none;\n    filter: drop-shadow(10px 10px 0 rgba(0,0,0,0.5));\n    transition: 5s;\n}\nsection:active .plane\n{\n    max-width: 500px;\n    filter: drop-shadow(200px 200px 0 rgba(0,0,0,0.5));\n}\n.clouds\n{\n    position: absolute;\n    left: 0;\n    width: 100%;\n    height: 100%;\n    z-index: 10000;\n    pointer-events: none;\n    opacity: 0;\n    transition: opacity 2s;\n    transition-delay: 0s;\n}\nsection:active .clouds\n{\n    opacity: 1;\n    transition-delay: 1s;\n}\n.clouds img\n{\n    position: absolute;\n    left: 0;\n    width: 800px;\n    animation: animateClouds 4s linear infinite;\n    animation-delay: calc(-1.5s * var(--i));\n}\n.clouds2\n{\n    right: 0;\n    transform: rotate(180deg);\n}\n@keyframes animateClouds\n{\n    0%\n    {\n        transform: translateY(-100%);\n    }\n    100%\n    {\n        transform: translateY(100%);\n    }\n}"
