      "html": "<div class=\"form\">\r\n         <h2>Login</h2>\r\n         <div class=\"input\">\r\n             <div class=\"inputbox\">\r\n                 <label for=\"name\">Username</label>\r\n                 <input type=\"text\" name=\"name\" placeholder=\"example@xyz.com\">\r\n             </div>\r\n             <div class=\"inputbox\">\r\n                 <label for=\"pass\">Password</label>\r\n                 <input type=\"password\" name=\"pass\" placeholder=\"**********\">\r\n             </div>\r\n             <div class=\"inputbox\">\r\n                 <input type=\"submit\" value=\"Sign In\">\r\n             </div>\r\n             <div class=\"forget\">\r\n                <a href=\"#\">Forget Password?</a>\r\n             </div>\r\n             <div class=\"signup\">\r\n                 <a href=\"#\">Sign Up</a>\r\n             </div>   \r\n         </div>\r\n     </div>",
      "css": "/* style.css */\n*\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n}\r\nbody\r\n{\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    min-height: 100vh;\r\n    background: #ebf5fc;\r\n}\r\n.form\r\n{\r\n    position: relative;\r\n    width: 350px;\r\n    padding: 40px 40px 60px;\r\n    background: #ebf5fc;\r\n    border-radius: 10px;\r\n    text-align: center;\r\n    box-shadow: -5px -5px 15px rgba(255,255,255,0.8),\r\n                5px 5px 10px rgba(0,0,0,0.1);\r\n}\r\n.form h2\r\n{\r\n    color: #32a3b1;\r\n    font-weight: 500;\r\n    font-family: arial;\r\n}\r\n.form .input\r\n{\r\n    text-align: left;\r\n    margin-top: 40px;\r\n}\r\n.form .input .inputbox\r\n{\r\n    margin-top: 20px;\r\n}\r\n.form .input .inputbox label\r\n{\r\n    display: block;\r\n    color: #868686;\r\n    margin-bottom: 5px;\r\n    font-size: 18px;\r\n}\r\n.form .input .inputbox input\r\n{\r\n    width: 100%;\r\n    height: 50px;\r\n    background: #ebf5fc;\r\n    border: none;\r\n    outline: none;\r\n    border-radius: 40px;\r\n    padding: 5px 15px;   \r\n    font-size: 18px;\r\n    color: #32a3b1;\r\n    box-shadow: inset -2px -2px 6px rgba(255,255,255,1),\r\n                inset 2px 2px 6px rgba(0,0,0,0.1);\r\n}\r\n.form .input .inputbox input[type=\"submit\"]\r\n{\r\n    margin-top: 20px;\r\n    box-shadow: -2px -2px 6px rgba(255,255,255,1),\r\n                 2px 2px 6px rgba(0,0,0,0.1);\r\n}\r\n.form .input .inputbox input[type=\"submit\"]:hover\r\n{\r\n    color: #006c9c;\r\n    margin-top: 20px;\r\n    box-shadow: inset -2px -2px 6px rgba(255,255,255,1),\r\n                 inset 2px 2px 6px rgba(0,0,0,0.1);\r\n}\r\n.form .input .inputbox input::placeholder\r\n{\r\n    color: #bdcada;\r\n    font-family: cursive;\r\n    font-size: 18px;\r\n}\r\n.forget\r\n{\r\n    margin-top: 30px;\r\n    text-align: center;\r\n}\r\n.forget a\r\n{\r\n    text-decoration: none;\r\n    font-size: 18px;\r\n    color: #999aaa;\r\n}\r\n.forget a:hover\r\n{\r\n    color: #444;\r\n}\r\n.signup\r\n{\r\n    margin-top: 30px;\r\n    text-align: center;\r\n}\r\n.signup a\r\n{\r\n    text-decoration: none;\r\n    color: #ff0047;\r\n    font-size: 18px;\r\n    font-family: arial;\r\n}\r\n.signup a:hover\r\n{\r\n    color: #4700ff;\r\n}"
