      "css": "/* style.css */\nbody\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    height: 100vh;\r\n    background: #112c38;\r\n    font-family: arial;\r\n}\r\nul\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    display: flex;\r\n}\r\nul li\r\n{\r\n    list-style: none;\r\n    margin: 0 20px;\r\n    transition: 0.5s;\r\n}\r\nul li a\r\n{\r\n   display: block;\r\n    position: relative;\r\n    text-decoration: none;\r\n    padding: 10px;\r\n    font-size: 20px;\r\n    color: #fff;\r\n    text-transform: uppercase;\r\n    transition: 0.5s;\r\n}\r\nul:hover li a\r\n{\r\n    transform: scale(1.5);\r\n    opacity: 0.2;\r\n    filter: blur(5px);\r\n}\r\nul li a:hover\r\n{\r\n    transform: scale(2);\r\n    opacity: 1;\r\n    filter: blur(0);\r\n}\r\nul li a:before\r\n{\r\n    content: '';\r\n    position: absolute;\r\n    top: 0;\r\n    left: 0;\r\n    width: 100%;\r\n    height: 100%;\r\n    background: #ff497c;\r\n    transition: transform 0.5s;\r\n    transform-origin: right;\r\n    transform: scaleX(0);\r\n    z-index: -1;\r\n}\r\nul li a:hover:before\r\n{\r\n    transition: transform 0.5s;\r\n    transform-origin: left;\r\n    transform: scaleX(1);\r\n}"
