    "code": {
      "html": "<div class=\"box\">\r\n        <div class=\"inputBox\">\r\n            <input type=\"password\" id=\"password\" placeholder=\"password\" onkeyup=\"checkPassword(this.value)\">\r\n            <span id=\"toggleBtn\"></span>\r\n        </div>\r\n        <div class=\"validation\">\r\n            <ul>\r\n                <li id=\"lower\">At least one lowercase character</li>\r\n                <li id=\"upper\">At least one uppercase character</li>\r\n                <li id=\"number\">At least one number</li>\r\n                <li id=\"special\">At least one special character</li>\r\n                <li id=\"length\">At least 8 character</li>\r\n            </ul>\r\n        </div>\r\n    </div>\r\n\r\n    ",
      "css": "/* style.css */\n@import url('https://fonts.googleapis.com/css2?family=Open+Sans:wght@300;400;500;600;700;800&display=swap');\r\n*\r\n{\r\n    margin: 0;\r\n    padding: 0;\r\n    box-sizing: border-box;\r\n    font-family: 'Open Sans', sans-serif;\r\n}\r\nbody\r\n{\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n    min-height: 100vh;\r\n    background: #8cccff;\r\n}\r\n.box\r\n{\r\n    position: relative;\r\n    width: 300px;\r\n}\r\n.box .inputBox\r\n{\r\n    position: relative;\r\n    width: 100%;\r\n    background: #fff;\r\n    padding: 5px;\r\n    border-radius: 8px;\r\n    box-shadow: 0 15px 25px rgba(0,0,0,0.15);\r\n}\r\n.box .inputBox input\r\n{\r\n    position: relative;\r\n    width: 100%;\r\n    outline: none;\r\n    border: none;\r\n    padding: 10px 5px;\r\n}\r\n.box .inputBox  #toggleBtn\r\n{\r\n    position: absolute;\r\n    top: 8px;\r\n    right: 10px;\r\n    width: 34px;\r\n    height: 34px;\r\n    background: rgba(0,0,0,0.05);\r\n    border-radius: 50%;\r\n    cursor: pointer;\r\n    display: flex;\r\n    justify-content: center;\r\n    align-items: center;\r\n}\r\n.box .inputBox #toggleBtn::before\r\n{\r\n    content: '\\f06e';\r\n    font-family: fontAwesome;\r\n}\r\n.box .inputBox #toggleBtn.hide::before\r\n{\r\n    content: '\\f070';\r\n    font-family: fontAwesome;\r\n}\r\n\r\n.validation\r\n{\r\n    background: #376488;\r\n    padding: 10px;\r\n    margin-top: 30px;\r\n    border-radius: 8px;\r\n    box-shadow: 0 15px 25px rgba(0,0,0,0.15);\r\n}\r\n.validation ul\r\n{\r\n    position: relative;\r\n    display: flex;\r\n    flex-direction: column;\r\n    gap: 8px;\r\n}\r\n.validation ul li\r\n{\r\n    position: relative;\r\n    list-style: none;\r\n    color: #fff;\r\n    font-size: 0.85em;\r\n    transition: 0.5s;\r\n}\r\n.validation ul li.valid\r\n{\r\n    color: rgba(255,255,255,0.5);\r\n}\r\n.validation ul li::before\r\n{\r\n    content: '\\f192';\r\n    font-family: fontAwesome;\r\n    width: 20px;\r\n    height: 10px;\r\n    display: inline-flex;\r\n}\r\n.validation ul li.valid::before\r\n{\r\n    content: '\\f00c';\r\n    color: #0f0;\r\n}",
      "js": "// app.js\nconst password = document.getElementById('password');\r\nconst passValue = password.value;\r\nconst toggleBtn = document.getElementById('toggleBtn');\r\n\r\nconst lowerCase = document.getElementById('lower');\r\nconst upperCase = document.getElementById('upper');\r\nconst digit = document.getElementById('number');\r\nconst specialChar = document.getElementById('special');\r\nconst minLength = document.getElementById('length');\r\n\r\n//check password\r\nconst checkPassword = (data) => {\r\n    const lower = new RegExp('(?=.*[a-z])');\r\n    const upper = new RegExp('(?=.*[A-Z])');\r\n    const number = new RegExp('(?=.*[0-9])');\r\n    const special = new RegExp('(?=.*[!@#\\$%\\^&\\*])');\r\n\r\n    // lowercase validation check\r\n    if(lower.test(data))\r\n    {\r\n        lowerCase.classList.add('valid');\r\n    } else {\r\n        lowerCase.classList.remove('valid');\r\n    }\r\n\r\n    // upperCase validation check\r\n    if(upper.test(data))\r\n    {\r\n        upperCase.classList.add('valid');\r\n    } else {\r\n        upperCase.classList.remove('valid');\r\n    }\r\n\r\n    // nuber validation check\r\n    if(number.test(data))\r\n    {\r\n        digit.classList.add('valid');\r\n    } else {\r\n        digit.classList.remove('valid');\r\n    }\r\n\r\n    // special character validation check\r\n    if(special.test(data))\r\n    {\r\n        specialChar.classList.add('valid');\r\n    } else {\r\n        specialChar.classList.remove('valid');\r\n    }\r\n\r\n    // length validation check\r\n    if(password.value.length >= 8)\r\n    {\r\n        minLength.classList.add('valid');\r\n    } else {\r\n        minLength.classList.remove('valid');\r\n    }\r\n}\r\n\r\n// show hide password\r\ntoggleBtn.onclick = function(){\r\n    if(password.type === 'password'){\r\n        password.setAttribute('type', 'text');\r\n        toggleBtn.classList.add('hide');\r\n    } else {\r\n        password.setAttribute('type', 'password');\r\n        toggleBtn.classList.remove('hide');\r\n    }\r\n}"
    }
